using System;using System.Globalization;using System.IO;using System.Windows.Data;using System.Windows.Media.Imaging;
namespace PhotoBooth.Admin.UI.Converters { public sealed class ByteArrayImageConverter:IValueConverter { public object Convert(object value,Type t,object p,CultureInfo c){var bytes=value as byte[];if(bytes==null||bytes.Length==0)return null;var image=new BitmapImage();using(var stream=new MemoryStream(bytes)){image.BeginInit();image.CacheOption=BitmapCacheOption.OnLoad;image.StreamSource=stream;image.EndInit();image.Freeze();}return image;}public object ConvertBack(object v,Type t,object p,CultureInfo c)=>Binding.DoNothing;} }
